def load_config_file(config_path: str) -> dict:
    """Load training parameters from a JSON config file.

    Config files are generated by trainit-gui and contain training parameters.
    Metadata fields (starting with '_') are ignored.

    Args:
        config_path: Path to JSON config file

    Returns:
        Dictionary of training parameters

    Raises:
        FileNotFoundError: If config file doesn't exist
        ValueError: If config file is invalid JSON
    """
    import json
    from pathlib import Path

    path = Path(config_path)
    if not path.exists():
        raise FileNotFoundError(f"Config file not found: {config_path}")

    try:
        with open(path, "r") as f:
            config = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in config file: {e}")

    # Filter out metadata fields (keys starting with '_')
    return {k: v for k, v in config.items() if not k.startswith("_")}


def merge_config_with_args(
    args: argparse.Namespace, config: dict, explicit: Optional[set] = None
) -> argparse.Namespace:
    """Apply config file values, except for options given explicitly on the CLI.

    explicit defaults to the options present in sys.argv (see explicit_cli_dests).
    A config device of "auto" keeps the detected default device.
    """
    if explicit is None:
        explicit = explicit_cli_dests()

    for key, value in config.items():
        if value is None:
            continue
        attr_name = key.replace("-", "_")
        if not hasattr(args, attr_name):
            logger.warning(f"Unknown config parameter ignored: {key}")
            continue
        if attr_name in explicit:
            continue
        if attr_name == "device" and value == "auto":
            continue
        setattr(args, attr_name, value)
        logger.debug(f"Using config value for {attr_name}: {value}")

    return args


def fit_error_model_after_training(config: "YOLOTrainingConfig", results) -> Optional[Path]:
    """Fit error_model.json for best.pt on the val split; None (with a warning) if that is not possible."""
    from trainit import fit_error_model

    dataset = yaml.safe_load(config.data_path.read_text())
    if not dataset.get("val") or dataset.get("val") == dataset.get("train"):
        logger.warning("No separate val split: error_model.json not fitted (box sigma will use defaults)")
        return None
    weights = Path(results.save_dir) / "weights" / "best.pt"
    metrics = {key: value for key, value in (getattr(results, "results_dict", None) or {}).items()
               if isinstance(value, (int, float))}
    try:
        document = fit_error_model.fit(weights, config.data_path, imgsz=config.imgsz, device=config.device,
                                       metrics=metrics)
    except (OSError, ValueError, KeyError) as e:
        logger.warning(f"Error model not fitted: {e}")
        return None
    return fit_error_model.write(document, weights)


def build_arguments_string(args: argparse.Namespace) -> str:
    """Return every CLI option that has a value as a reproducible argument string."""
    from savant_common.provenance import arguments_string

    return arguments_string(build_parser(), args)


def main():
    """Main function to execute YOLO OBB training."""
    try:
        # Parse arguments
        args = parse_arguments()

        # Load config file if provided and merge with CLI args
        if args.config:
            try:
                config_data = load_config_file(args.config)
                args = merge_config_with_args(args, config_data)
            except (FileNotFoundError, ValueError) as e:
                print(f"Error loading config file: {e}", file=sys.stderr)
                sys.exit(1)

        # Validate that --data is provided (required)
        if not args.data:
            print(
                "Error: --data is required (either via CLI or config file)",
                file=sys.stderr,
            )
            sys.exit(1)

        # Capture start time for provenance tracking
        start_time = None
        if args.provenance:
            from datetime import datetime, timezone

            start_time = datetime.now(timezone.utc)

        # Setup logging
        setup_logging(args.verbose)

        if args.config:
            logger.info(f"Loaded config from: {args.config}")

        logger.info(f"SAVANT trainit v{__version__}")

        # Setup local Ultralytics settings before importing YOLO
        # This must be done before any ultralytics import
        setup_ultralytics_settings(project_dir=args.project)

        # Now import ultralytics (after settings are configured)
        try:
            from ultralytics import YOLO
            import ultralytics.utils as ultralytics_utils
        except ImportError:
            logger.error("Error: ultralytics package not found. Please install it:")
            logger.error("pip install ultralytics")
            sys.exit(1)

        # Configure Ultralytics/YOLO logging
        if not args.verbose:
            ultralytics_utils.LOGGER.setLevel(logging.WARNING)
            logger.info("YOLO output suppressed (use --verbose to enable)")
        else:
            ultralytics_utils.LOGGER.setLevel(logging.INFO)
            logger.info("YOLO verbose output enabled")

        # Create configuration
        config = YOLOTrainingConfig(args)
        logger.info("Training configuration validated successfully")

        # Create trainer and execute training
        trainer = YOLOTrainer(config, YOLO)
        trainer.load_model()
        results = trainer.train()
        error_model = None
        if results is not None and not args.no_error_model:
            error_model = fit_error_model_after_training(config, results)

        # Record provenance if enabled
        if args.provenance and results is not None:
            from datetime import datetime, timezone
            import torch
            import ultralytics
            from savant_common.provenance import load_or_create_chain

            end_time = datetime.now(timezone.utc)

            chain = load_or_create_chain(
                args.provenance,
                entity_id="savant_trainit_output",
                initial_source=str(args.data),
                description="SAVANT trainit YOLO OBB model training",
            )

            # Build arguments string
            arguments = build_arguments_string(args)

            # Inputs: dataset YAML and pre-trained model
            inputs = [str(args.data), args.model]
            input_formats = ["YAML", "PT"]

            # Outputs: best.pt and last.pt from training results
            weights_dir = Path(results.save_dir) / "weights"
            outputs = [str(weights_dir / "best.pt"), str(weights_dir / "last.pt")]
            output_formats = ["PT", "PT"]
            if error_model:
                from scenario_uncertainty.provenance import output_format

                outputs.append(str(error_model))
                output_formats.append(output_format("model", 1))

            chain.add(
                started_at=start_time.isoformat().replace("+00:00", "Z"),
                ended_at=end_time.isoformat().replace("+00:00", "Z"),
                tool_name="train_yolo_obb",
                tool_version=__version__,
                operation="YOLO OBB model training",
                inputs=inputs,
                input_formats=input_formats,
                outputs=outputs,
                output_formats=output_formats,
                arguments=arguments,
                capture_agent=True,
                agent_type="automated",
                capture_environment=True,
                custom_properties={
                    "activity:savant:ultralytics_version": ultralytics.__version__,
                    "activity:savant:torch_version": torch.__version__,
                    "activity:savant:base_model": args.model,
                },
            )

            chain.save(args.provenance)
            logger.info(f"Provenance recorded to {args.provenance}")

        logger.info("Training workflow completed successfully")

    except KeyboardInterrupt:
        logger.info("Training interrupted by user")
        sys.exit(1)
    except (ValidationError, TrainingError) as e:
        logger.error(f"Training failed: {e}")
        sys.exit(1)
    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        if logger.isEnabledFor(logging.DEBUG):
            import traceback

            traceback.print_exc()
        sys.exit(1)


if __name__ == "__main__":
    main()
